def compute(vars):
    incurred_losses = vars["Incurred Losses"]
    loss_adjustment_expenses = vars["Loss Adjustment Expenses"]
    other_underwriting_expenses = vars["Other Underwriting Expenses"]
    earned_premiums = vars["Earned Premiums"]

    total_underwriting_costs = (
        incurred_losses
        + loss_adjustment_expenses
        + other_underwriting_expenses
    )

    if earned_premiums == 0:
        return None

    combined_ratio = total_underwriting_costs / earned_premiums

    return {
        "value": combined_ratio,
        "trace": {
            "Incurred Losses": incurred_losses,
            "Loss Adjustment Expenses": loss_adjustment_expenses,
            "Other Underwriting Expenses": other_underwriting_expenses,
            "Earned Premiums": earned_premiums,
            "Total Underwriting Costs": total_underwriting_costs,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
